/* ---------------------------------------------------------------------------- *
 * The audio jitter STAGE: every buffering decision between the decoder and whatever plays.
 *
 * WHY THIS ONE IS A HANDLE AND THE DECODER'S ADMISSION IS NOT. Both hold a queue of frames. The
 * difference is what the LAW reads. The decode sequencer never looks at a compressed byte, so its
 * door moves frame ids and the caller keeps the payloads. This stage's whole product IS the
 * samples — it hands back a steady stream of them, in an order it chose, split at offsets it chose
 * — so the samples live where the decisions are. Rust owns the stage, the caller holds an opaque
 * token, and samples cross once each way through (ptr, len): one memcpy of ten milliseconds of
 * audio per push, under half a megabyte a second at the push cadence.
 *
 * Exactly one _free per _new, and NULL is inert at every entry point — a failed new cannot become
 * a crash in deinit. No two calls on one handle may overlap: the mutators take the object
 * exclusively, so a concurrent call is aliasing, not a lost update. The Swift owner confines it to
 * one thread, which is the same discipline the Swift original documented.
 *
 * WHAT IS NOT HERE: the lock-free hand-off ring the render callback drains. That is raw storage
 * partitioned by two atomic counters, the one structure in the audio path that exists to keep a
 * real-time thread from ever blocking on the producer, and it belongs to the runtime that owns the
 * audio unit. The pump's own arithmetic IS here, as pure entries.
 * ---------------------------------------------------------------------------- */

typedef struct SlopDeskAudioStage SlopDeskAudioStage;

typedef struct {
  uint64_t frames_pushed;
  uint64_t late_dropped;       /* arrived at or behind the play frontier */
  uint64_t duplicate_dropped;  /* a re-delivery of a pending frame */
  uint64_t overflow_dropped;   /* skipped forward past the high-water mark */
  uint64_t underruns;          /* ran dry mid-play; priming silence is not one */
  uint64_t silence_samples;
} SlopDeskAudioStageStats;

typedef struct {
  size_t channels;
  size_t target_depth_frames;
  size_t high_water_frames;
} SlopDeskAudioStageShape;

SlopDeskAudioStage *slopdesk_audio_stage_new(size_t channels, size_t target_depth_frames,
                                             size_t high_water_frames);
void                slopdesk_audio_stage_free(SlopDeskAudioStage *handle);

SlopDeskAudioStageShape slopdesk_audio_stage_shape(SlopDeskAudioStage *handle);
SlopDeskAudioStageStats slopdesk_audio_stage_stats(SlopDeskAudioStage *handle);
bool   slopdesk_audio_stage_primed(SlopDeskAudioStage *handle);
size_t slopdesk_audio_stage_pending_frames(SlopDeskAudioStage *handle);
size_t slopdesk_audio_stage_available_samples(SlopDeskAudioStage *handle);

void   slopdesk_audio_stage_push(SlopDeskAudioStage *handle, uint32_t seq,
                                 const float *samples, size_t samples_len);
void   slopdesk_audio_stage_pull(SlopDeskAudioStage *handle, float *out, size_t out_len);
size_t slopdesk_audio_stage_drain_available(SlopDeskAudioStage *handle, float *out, size_t out_len);
void   slopdesk_audio_stage_note_consumer_starved(SlopDeskAudioStage *handle);
void   slopdesk_audio_stage_drop_oldest_pending(SlopDeskAudioStage *handle);
void   slopdesk_audio_stage_clear(SlopDeskAudioStage *handle);
size_t slopdesk_audio_stage_shed_to_depth_bound(SlopDeskAudioStage *handle, size_t ring_fill,
                                                size_t samples_per_frame);

/* The pump's arithmetic — pure, so the near side spells none of it. */
size_t slopdesk_audio_ring_target_samples(size_t target_depth_frames, size_t samples_per_frame);
size_t slopdesk_audio_high_water_samples(size_t high_water_frames, size_t samples_per_frame);
bool   slopdesk_audio_consumer_starved(bool primed, bool emitted_since_prime,
                                       uint64_t shortfall_now, uint64_t last_shortfall);

/* ---------------------------------------------------------------------------- *
 * Which decoded frame this refresh shows, and when.
 *
 * The presentation policy is a fold the caller copies out, folds into and writes back, so it
 * crosses BY VALUE — the decoder admission's shape, for the decoder admission's reason. What is big
 * here is the queue of waiting frames, and the near side never reads it: it reads a handle to
 * present and a list of handles to let go of. Nothing in the law dereferences a handle, so the
 * decoder's image buffers stay exactly where they are.
 *
 * WHAT THE NEAR SIDE MUST HONOUR. One refresh answers with an outcome and a DROP LIST. The outcome
 * says what to put on screen; the list says which images the queue no longer refers to — the trim
 * homeostasis performed to reach the frame it chose. A queue of opaque handles owes its caller that
 * list: a count would say how many died and leave the caller inferring WHICH from an ordering it is
 * deliberately not keeping. A submission answers the same way for the hard cap's own eviction.
 *
 * TWO DEPTH DOORS, BECAUSE THERE ARE TWO CONTROLLERS. set_live_depth carries the promote rule — a
 * deeper buffer re-primes, or the slack frame it was asked for never gets built. adopt_live_depth
 * does not, and is the older arrival-jitter controller's door: that one recommends a depth on every
 * frame and every underrun, and re-priming that often would hold the picture where the user can see
 * it. The two controllers are mutually exclusive upstream, so the two doors never both apply.
 *
 * There is no equality door here either, for the reason the decode sequencer has none: nothing on
 * the Swift side compares two queues.
 * ---------------------------------------------------------------------------- */

#define SLOPDESK_PRESENT_PRIMING 0u  /* still filling — re-show last_shown, if any */
#define SLOPDESK_PRESENT_PRESENT 1u  /* put `frame` on screen */
#define SLOPDESK_PRESENT_RESHOW  2u  /* the producer fell behind — re-show last_shown */

/* The deepest queue any configuration may ask for, which the crossing is sized for exactly. */
#define SLOPDESK_PRESENT_QUEUE_CAPACITY 16

typedef struct {
  uint64_t handle;       /* the caller's own handle; the law never looks inside it */
  double   submitted_at; /* the caller's monotonic seconds */
} SlopDeskQueuedFrame;

typedef struct {
  SlopDeskQueuedFrame queue[SLOPDESK_PRESENT_QUEUE_CAPACITY]; /* oldest first, first len live */
  size_t   len;
  uint64_t last_shown;   /* live only when has_last_shown */
  uint32_t max_depth;
  uint32_t live_depth;
  uint32_t underflow_run;
  bool     has_last_shown;
  bool     primed;
} SlopDeskPresentQueue;

typedef struct {
  SlopDeskPresentQueue queue;
  uint64_t evicted;      /* live only when has_evicted */
  bool     was_empty;    /* what the present-on-arrival gate reads, unrecoverable afterwards */
  bool     has_evicted;
} SlopDeskPresentSubmit;

typedef struct {
  SlopDeskPresentQueue queue;
  SlopDeskQueuedFrame  frame;  /* live only when kind is SLOPDESK_PRESENT_PRESENT */
  uint64_t dropped[SLOPDESK_PRESENT_QUEUE_CAPACITY]; /* oldest first, first dropped_len live */
  size_t   dropped_len;
  uint64_t last_shown;         /* live only when has_last_shown */
  uint32_t kind;               /* one of the SLOPDESK_PRESENT_* codes */
  bool     has_last_shown;
  bool     transient_dip;      /* a real starvation — the cue to grow the buffer */
  bool     re_primed;          /* also the cue to reset the jitter estimator */
} SlopDeskPresentStep;

typedef struct {
  double   playout_hard_ceiling_seconds;
  double   render_cap_slack_seconds;
  double   min_tick_hz;
  double   max_tick_hz;
  size_t   queue_capacity;
  uint32_t max_queue_depth;
  uint32_t playout_recompute_every;
} SlopDeskPresentConstants;

typedef struct {
  uint32_t next_samples;
  bool     due;
} SlopDeskPlayoutRecompute;

/* Chunked BLOB reassembly — app icons (kind 0, PNG) and window previews (kind 1, JPEG). A HANDLE,
 * for the reason the audio stage is one: the assembly's whole product IS the bytes, held across
 * many calls, so folding it through a record would copy the accumulator on every chunk. The
 * completed bytes come in two steps because the near side cannot know their length until the chunk
 * that finishes them: the fold reports it, one take copies them out. Everything else is pure. */

typedef struct SlopDeskBlobAssembler SlopDeskBlobAssembler;

typedef struct {
  uint8_t icon;
  uint8_t preview;
  size_t  max_partial_blobs;
} SlopDeskBlobKinds;

typedef struct {
  uint64_t id;
  size_t   len;      /* ready for one take */
  uint16_t meta_a;
  uint16_t meta_b;
  uint8_t  kind;
  bool     complete;
} SlopDeskBlobFold;

SlopDeskBlobKinds      slopdesk_blob_kinds(void);
