  uint32_t span_length;
  uint32_t record_count;
  uint32_t arena_length;
  uint16_t protocol_version;
  uint16_t capture_width;
  uint16_t capture_height;
  uint16_t fps;
  int16_t scroll_dx;
  int16_t scroll_dy;
  uint16_t band_top;
