  uint16_t display_max_width;
  uint16_t display_max_height;
  uint16_t meta_a;
  uint16_t meta_b;
  uint16_t size_px;
  uint16_t max_width_px;
  uint16_t rtt_tenths_millis;
  uint16_t encode_tenths_millis;
