// ---------------------------------------------------------------------------
// PATH 4's CLIENT end — requests out, replies in. rust/slopdesk-dropd's
// `client` module owns every layout; the round trip is a test in that crate,
// which is the whole reason the client end lives there.
//
// A request crosses as its type byte plus the scalars any frame could carry and
// ONE borrowed blob: a name for an offer, a body for a chunk, nothing else. A
// chunk's 256 KiB body is borrowed all the way to the frame.
//
// The reply splitter is a HANDLE, because half a length prefix in one recv and
// the rest in the next is the normal case.
// ---------------------------------------------------------------------------

#define SLOPDESK_DROP_OK 0u
#define SLOPDESK_DROP_PENDING 1u
#define SLOPDESK_DROP_EMPTY 2u
#define SLOPDESK_DROP_UNKNOWN_TYPE 3u
#define SLOPDESK_DROP_TRUNCATED 4u
#define SLOPDESK_DROP_BAD_UTF8 5u
#define SLOPDESK_DROP_FRAME_TOO_LARGE 6u

typedef struct {
    uint32_t offset;
    uint32_t length;
} SlopDeskDropText;

typedef struct {
    uint32_t transfer_id;
    SlopDeskDropText reason;
    // The wire type byte: 6 helloAck, 7 accept, 8 complete, 9 failed.
    uint8_t kind;
    bool accepted;
    // The offending type byte, or a frame length over the cap.
    uint64_t detail;
} SlopDeskDropReply;

typedef struct SlopDeskDropDecoder SlopDeskDropDecoder;

// kind: 1 hello (file_size carries the version), 2 offer (blob is the name),
// 3 chunk (blob is the body), 4 finish, 5 cancel. Unknown kinds answer 0.
size_t slopdesk_drop_encode_request(uint8_t kind, uint32_t transfer_id, uint64_t file_size,
                                    const unsigned char *blob, size_t blob_len,
                                    unsigned char *out, size_t cap);

uint32_t slopdesk_drop_decode_reply(const unsigned char *payload, size_t payload_len,
                                    SlopDeskDropReply *out,
                                    unsigned char *arena, size_t arena_cap);

SlopDeskDropDecoder *slopdesk_drop_decoder_new(void);
void slopdesk_drop_decoder_free(SlopDeskDropDecoder *handle);
void slopdesk_drop_decoder_append(SlopDeskDropDecoder *handle,
                                  const unsigned char *chunk, size_t chunk_len);
uint32_t slopdesk_drop_decoder_next(SlopDeskDropDecoder *handle, SlopDeskDropReply *out,
                                    unsigned char *arena, size_t arena_cap);
size_t slopdesk_drop_decoder_buffered(SlopDeskDropDecoder *handle);

// 0 the only supported version, 1 the per-frame payload cap, 2 the body chunk
// size a client sends, 3 the hard ceiling on one offered file. Unknown: -1.
int64_t slopdesk_drop_constant(uint32_t index);


// ---------------------------------------------------------------------------
// The INSPECTOR channel's client end. rust/slopdesk-inspectord's `wire` module
// owns the frame: the 4-byte big-endian prefix, the 16 MiB cap, the three tags,
// the cursor-and-compact splitter.
//
// An event's BODY does not cross as a value: it is JSON the client parses into
// its own model, so a decode answers WHERE the body sits and the bytes stay in
// the caller's buffer.
// ---------------------------------------------------------------------------

#define SLOPDESK_INSPECTOR_OK 0u
#define SLOPDESK_INSPECTOR_PENDING 1u
#define SLOPDESK_INSPECTOR_TRUNCATED 2u
#define SLOPDESK_INSPECTOR_UNKNOWN_TYPE 3u
#define SLOPDESK_INSPECTOR_FRAME_TOO_LARGE 4u
// The body buffer was too small; `detail` says how much was needed and
// NOTHING was consumed — grow and call again.
#define SLOPDESK_INSPECTOR_AGAIN 5u

typedef struct {
    uint32_t body_offset;
    uint32_t body_length;
    // The wire type byte: 1 event, 2 keep-alive.
    uint8_t tag;
    // The offending tag, or a frame length over the cap.
    uint64_t detail;
} SlopDeskInspectorFrame;

typedef struct SlopDeskInspectorDecoder SlopDeskInspectorDecoder;

size_t slopdesk_inspector_encode_subscribe(int64_t from_seq, unsigned char *out, size_t cap);

uint32_t slopdesk_inspector_decode_payload(const unsigned char *payload, size_t payload_len,
                                           SlopDeskInspectorFrame *out);

SlopDeskInspectorDecoder *slopdesk_inspector_decoder_new(void);
void slopdesk_inspector_decoder_free(SlopDeskInspectorDecoder *handle);
void slopdesk_inspector_decoder_append(SlopDeskInspectorDecoder *handle,
                                       const unsigned char *chunk, size_t chunk_len);
uint32_t slopdesk_inspector_decoder_next(SlopDeskInspectorDecoder *handle,
                                         SlopDeskInspectorFrame *out,
                                         unsigned char *body, size_t body_cap);

// 0 the frame payload cap, 1 the length prefix's width, 2 the client's outbound
// tag. An unknown index answers -1.
int64_t slopdesk_inspector_constant(uint32_t index);


/* What a client video session says to the host, and what it does with the answers.
 *
 * The machine is six scalars and two rectangles, ALL of them read by the caller, so it crosses BY
 * VALUE — §4b — rather than as a handle a Swift `struct` copy would silently alias. A transition
 * mutates, so it steps a COPY and writes the machine back only once every lent buffer is big
 * enough: a call that did not fit is NOT a transition, and calling again with the reported shape
 * repeats the same one. A control message crosses as the encoded datagram the runtime sends. */
#define SLOPDESK_VIDEO_CLIENT_IDLE 0u
#define SLOPDESK_VIDEO_CLIENT_CONNECTING 1u
#define SLOPDESK_VIDEO_CLIENT_STREAMING 2u
#define SLOPDESK_VIDEO_CLIENT_REJECTED 3u
#define SLOPDESK_VIDEO_CLIENT_STOPPED 4u

#define SLOPDESK_VIDEO_TARGET_WINDOW 0u
#define SLOPDESK_VIDEO_TARGET_DISPLAY 1u

#define SLOPDESK_CLIENT_EFFECT_SEND_CONTROL 0u
#define SLOPDESK_CLIENT_EFFECT_PRIME_CURSOR_FLOW 1u
#define SLOPDESK_CLIENT_EFFECT_START_DECODE_PIPELINE 2u
#define SLOPDESK_CLIENT_EFFECT_STOP_DECODE_PIPELINE 3u
#define SLOPDESK_CLIENT_EFFECT_UPDATE_CAPTURE_SIZE 4u
#define SLOPDESK_CLIENT_EFFECT_APPLY_STREAM_CADENCE 5u
#define SLOPDESK_CLIENT_EFFECT_APPLY_SCROLL_OFFSET 6u
#define SLOPDESK_CLIENT_EFFECT_APPLY_CONTENT_MASK 7u
#define SLOPDESK_CLIENT_EFFECT_APPLY_DISPLAY_MAX 8u
#define SLOPDESK_CLIENT_EFFECT_APPLY_HOST_STATS 9u
#define SLOPDESK_CLIENT_EFFECT_SESSION_ENDED_BY_HOST 10u
#define SLOPDESK_CLIENT_EFFECT_SESSION_REJECTED_BY_HOST 11u

/* The scrim did not flip, so the view is not notified. */
#define SLOPDESK_SCRIM_UNCHANGED (-1)
#define SLOPDESK_SCRIM_HIDDEN 0
#define SLOPDESK_SCRIM_SHOWN 1

typedef struct {
  uint32_t state;
  uint32_t target_kind;
  uint32_t target_id;
  uint32_t stream_id;
  SlopDeskVideoSize viewport;
  SlopDeskVideoSize capture_size;
  SlopDeskVideoRect window_bounds_cg;
} SlopDeskVideoClientMachine;

/* One opaque-content rectangle, in capture pixels. */
typedef struct {
  uint16_t x;
  uint16_t y;
  uint16_t width;
  uint16_t height;
} SlopDeskVideoMaskRect;

/* One side effect. Which fields mean anything is decided by `kind`; the rest stay zero. */
typedef struct {
  uint32_t kind;
  /* SEND_CONTROL: the encoded datagram, as a run of the answer arena. */
  SlopDeskByteSpan control;
  /* START_DECODE_PIPELINE / UPDATE_CAPTURE_SIZE / APPLY_DISPLAY_MAX. */
  SlopDeskVideoSize size;
  /* START_DECODE_PIPELINE. */
  SlopDeskVideoRect bounds;
  /* APPLY_SCROLL_OFFSET. */
  int32_t dx;
  int32_t dy;
  /* The cadence, the round-trip tenths, or the band's top. */
  uint32_t first;
  /* The encode tenths, or the band's bottom. */
  uint32_t second;
  /* APPLY_CONTENT_MASK: a run of the lent rectangles. */
  uint32_t mask_offset;
  uint32_t mask_count;
  bool full_range;
} SlopDeskVideoClientEffect;

/* What one transition needs the caller to lend. */
typedef struct {
  size_t effects;
  size_t masks;
  size_t arena;
} SlopDeskVideoClientShape;

/* ---------------------------------------------------------------------------- *
 * The HOST session machine — the other end of the handshake the client machine above answers, and
 * it crosses the same way: nine scalars by VALUE, effects into two lent buffers, and a transition
 * that COMMITS only when the answer fits, so measuring is never a second transition.
 *
 * The three resolvers are ANSWERS, not callbacks. Exactly one can matter per message — the
 * message's own variant decides which — so the near side resolves that one against its live state
 * and hands the size across, where `resolved == false` is the reject its closure spelled as nil.
 * ---------------------------------------------------------------------------- */

#define SLOPDESK_VIDEO_SESSION_IDLE 0u
#define SLOPDESK_VIDEO_SESSION_LISTENING 1u
#define SLOPDESK_VIDEO_SESSION_STREAMING 2u
#define SLOPDESK_VIDEO_SESSION_STOPPED 3u

#define SLOPDESK_SESSION_EFFECT_SEND_CONTROL 0u
#define SLOPDESK_SESSION_EFFECT_START_CAPTURE 1u
#define SLOPDESK_SESSION_EFFECT_STOP_CAPTURE 2u
#define SLOPDESK_SESSION_EFFECT_RESIZE_CAPTURE 3u
#define SLOPDESK_SESSION_EFFECT_APPLY_STREAM_SETTINGS 4u
#define SLOPDESK_SESSION_EFFECT_APPLY_AUDIO_CONTROL 5u
#define SLOPDESK_SESSION_EFFECT_APPLY_PRIVACY_MODE 6u

typedef struct {
  uint32_t state;
  uint32_t window_id;
  uint32_t next_stream_id;
  uint32_t last_stream_id;
  uint32_t last_resize_epoch;
  uint16_t capture_width;
  uint16_t capture_height;
  bool is_display_target;
  bool full_range;
} SlopDeskVideoSessionMachine;

/* A size the near side settled on, or `resolved == false` for the REJECT. */
typedef struct {
  uint16_t width;
  uint16_t height;
  bool resolved;
} SlopDeskResolvedSize;

typedef struct {
  uint32_t kind;
  SlopDeskByteSpan control;
  uint32_t window_id;
  uint32_t epoch;
  uint32_t first;
  uint32_t second;
  uint16_t width;
  uint16_t height;
  bool enabled;
} SlopDeskVideoSessionEffect;

typedef struct {
  size_t effects;
  size_t arena;
} SlopDeskVideoSessionShape;

SlopDeskVideoSessionMachine slopdesk_video_session_new(uint32_t next_stream_id, bool full_range);
bool slopdesk_video_session_media_flowing(SlopDeskVideoSessionMachine machine);
